import { test, expect } from '@playwright/test';

test.describe('Add form (AC-6, AC-7)', () => {
  test('AC-6, AC-7: the form exposes the brief\'s controls and an empty Title is refused on add', async ({ page }) => {
    await page.goto('/');

    // The form exposes exactly the controls the brief names.
    await expect(page.getByRole('textbox', { name: 'Title', exact: true })).toBeVisible();
    await expect(page.getByLabel('Description')).toBeVisible();
    await expect(page.getByRole('button', { name: 'Add task', exact: true })).toBeVisible();

    // Leaving Title empty and clicking 'Add task' creates nothing.
    await page.getByRole('button', { name: 'Add task', exact: true }).click();
    await expect(page.getByRole('listitem')).toHaveCount(0);
    await expect(page.getByLabel('Title')).toBeFocused();
  });
});
